/*
 * A256418  Congrua (possible solutions to the congruum problem): numbers k
 *          such that there are integers x, y and z with k = x^2-y^2 =
 *          z^2-x^2.
 * https://oeis.org/A256418
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n-th distinct positive integer k such that k = x^2 –
 *            y^2 = z^2 – x^2; equivalently k = 4 * area of a Pythagorean
 *            triangle, i.e. k = 2 * a * b where (a,b,c) is a Pythagorean
 *            triple. The sequence is generated by a multiset of sequences k =
 *            base * d^2 for each primitive triple base = 2*a...
 * Range:     u8 none, u16 none, u32 n <= 1639, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

/* --------- helpers --------- */

static uint64_t my_gcd(uint64_t a, uint64_t b) {
    while (b) {
        uint64_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

/* --------- bases of primitive triples --------- */

static seq_t *bases = NULL;
static size_t  base_cnt = 0;

static void generate_bases(void)
{
    if (bases) return;              /* already generated */

    const size_t m_max = 2000;       /* upper bound for Euclid's parameters; covers >10000 terms */
    size_t   cap = (m_max * m_max) / 4 + 16;   /* rough upper bound */
    bases = (seq_t*)calloc(cap, sizeof(seq_t));
    if (!bases) abort();

    for (size_t m = 2; m <= m_max; ++m) {
        for (size_t n = 1; n < m; ++n) {
            if ( ((m ^ n) & 1) == 0 ) continue;          /* m,n not of opposite parity */
            size_t a = m*m - n*n;
            size_t b = 2*m*n;
            if (my_gcd(a, b) != 1) continue;             /* only primitive triples */
            seq_t base = (seq_t)2 * (seq_t)a * (seq_t)b;  /* k for d = 1   */
            if (base_cnt >= cap) {
                cap <<= 1;
                seq_t *tmp = (seq_t*)realloc(bases, cap * sizeof(seq_t));
                if (!tmp) abort();
                bases = tmp;
            }
            bases[base_cnt++] = base;
        }
    }
}

/* --------- heap of current candidates --------- */

typedef struct {
    seq_t  val;      /* current k value of the series */
    seq_t  base;     /* base k0 = 2*a0*b0   */
    size_t d;        /* current d (>=1)      */
} Node;

static Node *heap = NULL;        /* 1‑based heap array */
static size_t heap_len = 0;      /* number of nodes in heap */

static inline void heap_swap(Node *x, Node *y)
{
    Node tmp = *x;
    *x = *y;
    *y = tmp;
}

static void heapify_up(size_t pos)
{
    while (pos > 1) {
        size_t parent = pos >> 1;
        if (heap[parent].val <= heap[pos].val) break;
        heap_swap(&heap[parent], &heap[pos]);
        pos = parent;
    }
}

static void heapify_down(size_t pos)
{
    while (1) {
        size_t left  = pos << 1;
        if (left > heap_len) break;
        size_t right = left + 1;
        size_t smallest = left;
        if (right <= heap_len && heap[right].val < heap[left].val)
            smallest = right;
        if (heap[pos].val <= heap[smallest].val) break;
        heap_swap(&heap[pos], &heap[smallest]);
        pos = smallest;
    }
}

static inline void heap_push(Node n)
{
    heap[++heap_len] = n;
    heapify_up(heap_len);
}

static inline Node heap_pop(void)
{
    Node top = heap[1];
    heap[1] = heap[heap_len--];
    heapify_down(1);
    return top;
}

/* --------- cache for already computed sequence values --------- */

static seq_t *cache = NULL;
static size_t  cache_len = 0;
static size_t  cache_cap = 0;

/* --------- main public function --------- */

seq_t a(idx_t n)
{
    if (n == 0) return 0;            /* undefined, but return 0 for safety */

    /* one‑time construction */
    if (!bases) {
        generate_bases();

        /* allocate the heap */
        heap = (Node*)malloc((base_cnt + 1) * sizeof(Node));
        if (!heap) abort();
        heap_len = 0;
        for (size_t i = 0; i < base_cnt; ++i)
            heap_push((Node){.val = bases[i], .base = bases[i], .d = 1});

        /* initialize cache */
        cache_cap = 0;
        cache_len = 0;
        cache = NULL;
    }

    /* generate until we have at least n terms */
    while (cache_len < (size_t)n) {
        Node cur = heap_pop();

        /* store unique values only */
        if (cache_len == 0 || cur.val != cache[cache_len - 1]) {
            if (cache_len >= cache_cap) {
                cache_cap = cache_cap ? cache_cap << 1 : 64;
                seq_t *tmp = (seq_t*)realloc(cache, cache_cap * sizeof(seq_t));
                if (!tmp) abort();
                cache = tmp;
            }
            cache[cache_len++] = cur.val;
        }

        /* push next value from the same series */
        Node next;
        next.base = cur.base;
        next.d    = cur.d + 1;
        seq_t d64 = (seq_t)next.d;
        next.val = cur.base * d64 * d64;
        heap_push(next);
    }
    return cache[n - 1];
}
